set -o pipefail
cd webviews
(bun install --frozen-lockfile >/dev/null 2>&1 || bun install >/dev/null 2>&1)
fail=0
for f in src/agent-session/acpmux/CloudStartView.test.tsx src/agent-session/acpmux/SlashMenu.test.tsx src/agent-session/acpmux/conversation/ThinkingGlyph.test.tsx src/agent-session/acpmux/conversation/TranscriptActivityRow.test.tsx src/agent-session/acpmux/conversation/activityTone.test.ts src/agent-session/acpmux/conversation/backgroundRuns.test.tsx src/agent-session/acpmux/conversation/heldMessage.test.tsx src/agent-session/acpmux/conversation/messageSurfaces.test.ts src/agent-session/acpmux/conversation/pendingMessages.test.ts src/agent-session/acpmux/conversation/workedOutcome.test.ts src/agent-session/acpmux/conversation/zeroToolCalls.test.ts src/agent-session/acpmux/holdRefused.test.ts src/agent-session/acpmux/icons/forkIcon.test.ts src/agent-session/acpmux/icons/iconDefaultMarkup.test.tsx src/agent-session/acpmux/organizationFixture.test.ts src/agent-session/acpmux/place/place.test.tsx src/agent-session/acpmux/refreshRetention.test.ts src/agent-session/acpmux/rowEstimates.test.ts src/agent-session/acpmux/rowGapTable.test.ts src/agent-session/acpmux/rowLayoutLinearity.test.ts src/agent-session/acpmux/rows/parity.test.ts src/agent-session/acpmux/sendOffLook.test.ts src/agent-session/acpmux/sessionListGrowth.test.ts src/agent-session/acpmux/toastAvoidance.test.ts src/agent-session/acpmux/waitSpinners.test.ts src/pages/settings/channelsCard.test.tsx src/pages/settings/cloudEnvironmentsCard.test.tsx src/pages/settings/durationUnits.test.ts src/pages/settings/editors.test.tsx src/pages/settings/layout.test.ts src/pages/settings/lazyCards.test.ts src/pages/settings/mockProvider.test.ts src/pages/settings/render.test.tsx src/pages/settings/rowSummary.test.tsx src/pages/settings/sidebarSections.test.tsx src/pages/settings/sidebarSymbolsPaint.test.tsx src/pages/settings/themePane.test.tsx src/pages/settings/themeStudio.test.tsx src/pages/shared/linkDownGrace.test.tsx src/pages/shared/plainErrors.test.ts src/ui/SplitEdge.test.tsx ; do
  if timeout 200 bun test "$f" > /tmp/out.txt 2>&1; then echo "PASS $f"; else echo "FAIL $f"; grep -E "^\(fail\)|error:|Expected|Received|TypeError" /tmp/out.txt | head -14; fail=1; fi
done
exit $fail
